function deposit(address token, uint amount) external nonReentrant {
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        uint value = Oracle(link).getPriceUSD(token).mul(amount).div(uint256(10)**ERC20Detailed(token).decimals());
        require(value > 0, "!value");
        _mint(address(this), value); // Amount of fUSD to mint

        IERC20(token).safeApprove(unirouter, 0);
        IERC20(token).safeApprove(unirouter, amount);

        IERC20(address(this)).safeApprove(unirouter, 0);
        IERC20(address(this)).safeApprove(unirouter, value);
        
        (,,uint liquidity) = UniswapRouter(unirouter).addLiquidity(
            token,
            address(this),
            amount,
            value,
            0,
            0,
            address(this),
            now.add(1800)
        );

        address pair = IUniswapV2Factory(UniswapRouter(unirouter).factory()).getPair(token, address(this));
        require(pair != address(0), "!pair");
        if (tokens[pair] == address(0)) {
            tokens[pair] = address(new SupplyToken(
                string(abi.encodePacked(ERC20Detailed(token).symbol(), " ", ERC20Detailed(pair).name())),
                string(abi.encodePacked(ERC20Detailed(token).symbol(), ERC20Detailed(pair).symbol())),
                ERC20Detailed(pair).decimals()
            ));
        }
        
        SupplyToken(tokens[pair]).mint(msg.sender, liquidity);
        uint dust = IERC20(token).balanceOf(address(this));
        if (dust > 0){
            IERC20(token).safeTransfer(msg.sender, dust);
        }
    }

function deposit(uint256 poolId, uint256 amount) external payable {
        PoolInfo memory poolInfoMem = poolsInfo[poolId];
        if(poolInfoMem.payoutIsEth){
            uint256 amountForFee = msg.value * feePercent / 100;
            if(amountForFee > 0){
                (bool success,) = feeReceiverEth.call{value: amountForFee}("");
                require(success, "Distribution failed");
            }
            poolInfoMem.amountForReward += msg.value - amountForFee;
        } else {
            require(msg.value == 0, "Don't send a value for token deposits");
            uint256 amountForFee = amount * feePercent / 100;
            SafeERC20.safeTransferFrom(IERC20(poolInfoMem.rewardAddress), msg.sender, address(this), amount);
            if(amountForFee > 0){
                SafeERC20.safeTransfer(IERC20(poolInfoMem.rewardAddress), feeReceiverTokens, amountForFee);
            }
            poolInfoMem.amountForReward += amount - amountForFee;
        }
        poolsInfo[poolId] = poolInfoMem;
    }

